sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetSecurityClearanceFromUser(strUserSysId,vExpected)
	{
		function TestCase_GetSecurityClearanceFromUser_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected === false)
			{
				return (vExpected === vResult);
			}
			return (vExpected == vResult);
		}
		
		test.TestCase(
			'Function GetSecurityClearanceFromUser()',
			GetSecurityClearanceFromUser,
			{
				'strUserSysId': strUserSysId
			},
			vExpected,
			TestCase_GetSecurityClearanceFromUser_CheckResult);
	}
		
	TestCase_GetSecurityClearanceFromUser(null,false);

	var testdata = new DataSilosTestDataAPI();

	var strUser0SysId = testdata.CreateUser('No Security Clearance');

	TestCase_GetSecurityClearanceFromUser(strUser0SysId,0);
	TestCase_GetSecurityClearanceFromUser(strUser0SysId,0);

	var strUser1SysId = testdata.CreateUser('Security Clearance Level 1');
	x_snc_devtools.RecordSetValue('sys_user',strUser1SysId,'x_snc_datasilos_security_clearance',1);

	TestCase_GetSecurityClearanceFromUser(strUser1SysId,1);
	TestCase_GetSecurityClearanceFromUser(strUser1SysId,1);

	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
